const $=selector=>document.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=url=>/^https:\/\//.test(url??'')?esc(url):'#';
const labels={disconnected:'未连接',available:'可连接',connected:'已连接',needs_auth:'需重新授权',error:'同步异常',needs_project:'待匹配项目',needs_info:'待补充验收',queued:'待执行',awaiting_approval:'待确认',dispatching:'派发中',running:'开发中',backfilling:'正在回填',review_ready:'待审阅 PR',failed:'执行失败'};
const messages={feishu_api_2091005:'当前授权账号无法读取这场妙记，请核对组织及分享权限；其他会议来源会继续处理。',source_check_failed:'会议来源暂时异常，其他来源会继续处理。',cloud_runner_failed:'云端开发或测试未通过。请打开云端运行核对日志，再修正配置并重试。',requirement_fidelity_failed:'代码与会议验收依据不一致，已阻止创建 PR。请核对下方检查结果。',requirement_review_unavailable:'需求证据核对服务暂不可用，请稍后重试。',requirement_review_incomplete:'需求证据核对尚未完成，当前不会发布 PR。',feishu_minutes_approval_required:'妙记读取权限尚未全部获批，当前不能自动读取会议内容或启动新连接的开发任务。请在公司审批通过后重新授权。',feishu_bootstrap_scope_unverified:'飞书未返回可核验的权限范围，当前连接尚未启用。',feishu_device_expired:'本次授权链接已过期，请重新授权；无需重新创建应用。',legacy_relay_active:'此 Repo 的旧版 Focus Board 接力仍在运行。请完成迁移验收并停用旧工作流后，再安装新执行器。',project_has_active_run:'项目有正在执行或回填的任务，请等待完成后再修改绑定。',oauth_configuration_required:'请先配置 OAuth 应用。',sign_in_required:'请先登录后打开工作台。',project_sync_failed:'GitHub 登录已成功，但项目同步失败。请在 Connector 中重试同步。',preauth_required:'登录会话已过期，请重新点击“使用 GitHub 登录”。',github_login_not_allowed:'当前部署采用邀请准入。请确认受邀 GitHub 账号，或联系部署者。',admin_required:'此入口仅限管理员。',invalid_invitation:'请填写有效的 GitHub 用户名，勿填邮箱；有效期为 1 至 30 天。',invitation_unavailable:'邀请已使用、过期或撤销，请重新打开有效邀请或联系邀请人。',invitation_account_mismatch:'请重新打开邀请链接，并选择受邀的 GitHub 账号。',account_disabled:'当前账号的访问已停用。',origin_mismatch:'请求来源不匹配，请刷新页面。',agent_not_connected:'请先连接所选 Agent。',github_connection_required:'请先授权 GitHub Connector。',runner_installation_required:'请在项目中安装云端执行器。',linear_team_required:'请选择这个 Linear 项目所属的团队。',different_account_disconnect_first:'这个 Connector 已绑定其他账号，请先断开原账号。',provider_http_403:'授权范围或组织策略阻止访问，请检查应用权限。',repository_already_managed:'这个 Repo 已由另一个项目管理，请先解除原绑定。',agent_key_missing:'请连接你自己的 Agent API Key。',agent_key_rejected:'密钥或模型接口校验失败，请核对所选 Agent 的网关和模型。',cli_intent_requires_explicit_restart:'上一次编码调用未留下完整结果。请先核对失败运行，再勾选重新准备；系统不会自动重复调用。',agent_protocol_invalid:'所选执行器与网关协议不匹配。',invalid_agent_endpoint:'请填写无查询参数的 HTTPS 模型 API 地址。',agent_endpoint_not_allowed:'该模型网关尚未列入部署者允许的主机清单。',feishu_event_subscription_failed:'飞书授权已保存，但新妙记订阅尚未成功。云端会重试；若持续失败，需由部署者核对商店应用的事件开放资格。',feishu_admin_approval_required:'请让所在公司的飞书管理员安装应用并批准妙记读取权限，再重新授权；无需自行创建应用。',feishu_app_not_installed:'所在公司的应用已停用或卸载，请联系飞书管理员恢复后重新授权。',feishu_application_unavailable:'应用尚未在你的公司安装或不在可用范围，请联系飞书管理员。',feishu_offline_scope_required:'飞书授权缺少离线访问，请让应用管理员开通 offline_access 后重新授权。',repository_already_bound:'这个 Repo 已绑定另一个项目，请先调整绑定。'};
let state,view='connectors',search='',refreshing=false,bootstrapTimer,bootstrapId,bootstrapRequest=0,invitationLink='';
async function api(path,body){
 const response=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'content-type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),signal:AbortSignal.timeout(30000)}).catch(error=>{if(error.name==='TimeoutError')throw new Error('请求超时，请检查网络后重试。');throw error;});
 const result=await response.json();if(!response.ok){const error=new Error(messages[result.error]||result.error||'请求失败');error.code=result.error;error.registration=result.registration;if(result.loginUrl)error.loginUrl=result.loginUrl;throw error;}return result;
}
function notice(text){$('#notice').textContent=text;$('#notice').hidden=!text;}
const badge=status=>`<span class="status ${['connected','review_ready'].includes(status)?'good':['needs_auth','failed','error','needs_project','needs_info'].includes(status)?'warn':''}">${esc(labels[status]||status)}</span>`;
function showModal(title,content){$('#modal-title').textContent=title;$('#modal-body').innerHTML=content;$('#modal').showModal();}
function closeModal(){$('#modal').close();$('#modal-body').replaceChildren();}
$('#close-modal').addEventListener('click',closeModal);
$('#modal').addEventListener('close',()=>{clearTimeout(bootstrapTimer);bootstrapId=null;bootstrapRequest++;$('#modal-body').replaceChildren();});
async function refresh(){
 if(refreshing)return;refreshing=true;
 try{state=await api('state');$('#project-count').textContent=state.projects.filter(p=>p.active).length;$('#task-count').textContent=state.tasks.length;$('#scheduler').textContent=state.scheduler?(state.connectors.find(c=>c.id==='feishu')?.discovery==='events'?'自动接收新妙记 · 每 5 分钟检查队列':'每 5 分钟检查会议')+(state.schedulerLast?' · 上次 '+new Date(state.schedulerLast.at).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})+(state.schedulerLast.status==='completed'?' 检查完成':state.schedulerLast.status==='partial'?' 部分来源异常，其他来源已检查':' 检查异常，将重试'):' · 等待首次检查'):'云端调度待配置';render();}
 catch(error){notice(error.message);if(error.code==='github_login_not_allowed')$('#logout').hidden=false;$('#content').innerHTML=error.loginUrl
  ?'<div class="empty"><div class="connector-icon">⑂</div><h2>使用 GitHub 登录</h2><p>'+ (error.registration==='open'?'使用 GitHub 登录即可创建自己的工作区，再连接会议、项目与 Agent。':'请使用已获准的 GitHub 账号登录；首次使用请打开部署者提供的邀请链接。') +'</p><a class="button" href="'+esc(error.loginUrl)+'">使用 GitHub 登录</a></div>'
  :'<div class="empty"><h2>暂时无法读取工作区</h2><p>请确认登录状态，或稍后刷新重试。</p></div>';}
 finally{refreshing=false;}
}
function render(){
 view=['projects','tasks',...(state.account?.admin?['beta']:[])].includes(location.hash.slice(1))?location.hash.slice(1):'connectors';$('#beta-nav').hidden=!state.account?.admin;
 const titles={beta:['邀请管理',state.registration==='open'?'当前已开放注册。用户可直接登录，也可使用账号邀请链接。':'创建按 GitHub 账号绑定的邀请，查看接受情况并撤销访问。'],connectors:['Connectors','连接会议、项目管理和执行 Agent。配置一次，让任务带着项目上下文进入开发。'],projects:['Projects','授权后自动同步项目。为需要执行的项目绑定 Repo、Agent 和验收规则。'],tasks:['Agent Tasks','从会议资料到开发成果。项目、原需求、云端运行与 Pull Request 始终关联。']};
 $('#page-title').textContent=titles[view][0];$('#page-subtitle').textContent=titles[view][1];document.querySelectorAll('[data-view]').forEach(a=>a.classList.toggle('active',a.dataset.view===view));
 renderOnboarding();
 if(view==='beta')renderBeta();else if(view==='connectors')renderConnectors();else if(view==='projects')renderProjects();else renderTasks();
}
async function renderBeta(){
 try{const {invites}=await api('admin/invites');if(view!=='beta')return;
 const statuses={pending:'待接受',accepted:'已接受',expired:'已过期',revoked:'已撤销'};
 $('#content').innerHTML=`<article class="project-card"><h2>创建账号邀请</h2><p class="modal-note">填写 GitHub 用户名。链接绑定该账号，接受后用户连接自己的会议、项目与 Agent。邀请不会自动发送。</p><form id="invite-form"><label for="invite-user">GitHub 用户名</label><input id="invite-user" name="login" required autocomplete="off" maxlength="39" placeholder="例如 octocat"><label for="invite-days">链接有效期</label><select id="invite-days" name="days"><option value="7">7 天</option><option value="3">3 天</option><option value="14">14 天</option></select><div class="form-footer"><button class="button" type="submit">创建邀请链接</button></div></form>${invitationLink?`<div class="info-box"><label for="new-invite-link">邀请链接（仅本次显示）</label><input id="new-invite-link" readonly value="${esc(invitationLink)}"><p>复制完整链接后发给受邀者；不要公开发布。刷新页面后不再显示。</p></div>`:''}</article><div class="project-list">${invites.map(i=>`<article class="project-card"><div class="project-heading"><h3>@${esc(i.login)}</h3><span class="status ${i.status==='accepted'?'good':''}">${esc(statuses[i.status])}</span></div><p class="modal-note">邀请创建于 ${new Date(i.createdAt).toLocaleString('zh-CN')} · ${i.status==='accepted'?'已接受，成员权限持续有效':'链接有效期至 '+new Date(i.expiresAt).toLocaleString('zh-CN')}</p>${i.status!=='revoked'?`<button class="quiet danger" data-revoke-invite="${esc(i.id)}">${i.status==='accepted'&&state.registration!=='open'?'撤销成员访问':'撤销邀请'}</button>`:''}</article>`).join('')||'<div class="empty"><p>还没有创建邀请。</p></div>'}</div>`;
 $('#invite-form').addEventListener('submit',e=>{e.preventDefault();perform(e.submitter,async()=>{const input=Object.fromEntries(new FormData(e.target)),result=await api('admin/invites',{login:input.login,days:Number(input.days)});invitationLink=result.url;await renderBeta();notice('邀请已创建，请复制链接并自行发送给受邀者。');});});
 $('#new-invite-link')?.addEventListener('click',e=>e.target.select());
 }catch(error){notice(error.message);}
}
function revokeInvitation(id){
 showModal('撤销邀请','<p>'+(state.registration==='open'?'当前已开放注册。撤销后邀请链接失效，账号仍可直接使用 GitHub 登录。':'未使用的邀请将立即失效。已接受的受邀成员将无法继续登录、启动新任务或通过 runner 发布结果。已在外部平台运行的作业不会被远程取消。部署者白名单和管理员权限独立保留。')+'</p><form id="revoke-invite-form"><button class="button" type="submit">确认撤销</button></form>');
 $('#revoke-invite-form').addEventListener('submit',e=>{e.preventDefault();perform(e.submitter,async()=>{const r=await api('admin/invites/'+id+'/revoke',{});invitationLink='';closeModal();await renderBeta();notice(r.accessDisabled?'邀请和成员访问已撤销。':'邀请已撤销；账号可按部署者当前的注册策略登录。');});});
}
function renderConnectors(){
 const sections=[['meeting','会议来源','发现会议并读取原文依据'],['project','项目管理','同步项目与来源需求'],['agent','执行 Agent','选择执行器及实际后端模型'],['repository','代码仓库','隔离开发、独立测试与 PR'],['delivery','成果回传','将结果写回原需求']];
 $('#content').innerHTML=sections.map(([kind,title,note])=>`<div class="category"><div class="category-head"><h2>${title}</h2><span>${note}</span></div><div class="cards">${state.connectors.filter(c=>(c.roles??[c.kind]).includes(kind)).map(c=>{
  const oauth=c.auth==='oauth';
  const controls=c.id==='gitlab'?`<button class="button secondary" data-gitlab="token">${c.status==='connected'?'更换 Access Token':'连接 GitLab'}</button>${c.connectionId&&c.status!=='disconnected'?`<button class="button secondary" data-sync="${c.connectionId}">同步项目</button>`:''}`:c.auth==='webhook'?`<button class="button secondary" data-webhook="meeting-webhook">${c.status==='connected'?'轮换接收密钥':'创建接收端点'}</button>`:oauth?`${c.id==='feishu'?'<button class="button '+(c.status==='connected'?'secondary':'')+'" data-bootstrap="feishu">'+(c.status==='connected'?'管理飞书授权':'扫码开通飞书连接')+'</button>':''}${c.configured&&c.identity?.onboarding!=='scan'?`<a class="button secondary" href="/api/oauth/${c.id}/start">${c.status==='connected'?'重新授权':'授权连接'}</a>`:c.id==='feishu'?'':'<span class="modal-note">部署者尚未配置共享应用，可使用自有应用。</span>'}${c.connectionId&&c.status!=='disconnected'?`<button class="button secondary" data-sync="${c.connectionId}">${kind==='meeting'?'检查会议':'同步项目'}</button>`:''}`:`<button class="button ${c.status==='connected'?'secondary':''}" data-agent="${c.id}">${c.status==='connected'?'更换密钥':'连接自己的 Agent'}</button>`;
  return `<article class="connector-card"><div class="card-title"><span class="connector-icon">${esc(c.icon)}</span><h3>${esc(c.name)}</h3>${badge(c.status)}</div><p>${esc(c.id==='feishu'&&c.discovery==='events'?'授权后自动接收新妙记，生成开发待办，无需创建应用。':c.description)}</p>${c.id==='feishu'&&c.discovery==='events'?'<p class="modal-note">连接后生成的新会议会自动处理；历史妙记不会自动扫描。公司策略可能要求管理员批准权限。</p>':''}<div class="capabilities">${c.capabilities.map(x=>`<span>${esc(x)}</span>`).join('')}</div>${c.setupStatus?.state==='awaiting_approval'?'<p class="error-line connector-error">扫码应用已创建；妙记读取权限等待公司审批，新连接尚未启用。</p>':''}${c.error?`<p class="error-line connector-error">${esc(messages[c.error]||c.error)}</p>`:''}<div class="card-footer"><div class="connection-meta">${esc(c.identity?.name||'等待连接')}${c.identity?.model?'<br>模型：'+esc(c.identity.model):''}<br>${c.lastSync?'同步于 '+new Date(c.lastSync).toLocaleString('zh-CN'):kind==='meeting'&&c.status==='connected'&&!state.connectors.some(a=>(a.roles??[a.kind]).includes('agent')&&a.status==='connected')?'授权已保存 · 待连接 Agent 后检查':'尚未同步'}</div><div class="card-actions">${controls}${c.connectionId&&c.status!=='disconnected'?`<button class="quiet danger" data-disconnect="${c.connectionId}">断开</button>`:''}</div></div>${oauth?`<details class="advanced"><summary>使用自有 OAuth 应用</summary><p>自托管或共享应用不适用于你的组织时，在这里配置自己的应用。</p><button class="quiet" data-config="${c.id}">配置应用</button></details>`:''}</article>`;
 }).join('')}</div></div>`).join('');
}
function renderOnboarding(){
 const connected=id=>state.connectors.some(c=>c.id===id&&c.status==='connected');
 const steps=[['GitHub 登录',connected('github')],['连接会议来源',connected('feishu')||connected('meeting-webhook')],['连接 Agent',state.connectors.some(c=>(c.roles??[c.kind]).includes('agent')&&c.status==='connected')],['绑定 Repo',state.projects.some(p=>p.active&&p.binding?.runnerReady)]];
 $('#onboarding').innerHTML=steps.every(s=>s[1])?'':`<section class="onboarding"><h2>接上你的第一条工作流</h2><p>授权你自己的账号，绑定项目。${connected('meeting-webhook')&&!connected('feishu')?'会议平台推送的纪要和待办会自动进入检查。':state.connectors.find(c=>c.id==='feishu')?.discovery==='events'||state.connectors.find(c=>c.id==='feishu')?.identity?.onboarding==='scan'?'授权后生成的新妙记会自动进入检查。':'最新可读妙记会进入检查，之后每五分钟发现新会议。'}</p><ol>${steps.map(([label,done],i)=>`<li class="${done?'done':''}"><span>${done?'✓':i+1}</span>${esc(label)}</li>`).join('')}</ol><a class="quiet" href="${(connected('feishu')||connected('meeting-webhook'))&&state.connectors.some(c=>(c.roles??[c.kind]).includes('agent')&&c.status==='connected')?'#projects':'#connectors'}">${(connected('feishu')||connected('meeting-webhook'))&&state.connectors.some(c=>(c.roles??[c.kind]).includes('agent')&&c.status==='connected')?'选择项目并绑定仓库':'配置 Connectors'} →</a></section>`;
 $('#account-label').textContent=state.account?.login||'';$('#logout').hidden=!state.account;$('#check-now').hidden=(!connected('feishu')&&!connected('meeting-webhook'))||!state.connectors.some(c=>(c.roles??[c.kind]).includes('agent')&&c.status==='connected');
}
function configureGitlab(){
 showModal('连接 GitLab Issues',`<p class="modal-note">使用 GitLab.com Personal Access Token（api 权限）。它用于读取项目、创建需求与回填评论，加密保存且不会回显。代码仍在你绑定的 GitHub Repo 中开发并创建 PR。</p><p><a target="_blank" rel="noopener noreferrer" href="https://gitlab.com/-/user_settings/personal_access_tokens">在 GitLab 创建 Token</a> · <a target="_blank" rel="noopener noreferrer" href="/assets/gitlab-connector.md">接入说明</a></p><form id="gitlab-form"><label for="gitlab-token">Personal Access Token</label><input id="gitlab-token" name="token" type="password" autocomplete="new-password" required minlength="10" maxlength="4096"><div class="form-footer"><button type="submit" class="button">验证并同步项目</button></div></form>`);
 $('#gitlab-form').addEventListener('submit',async e=>{e.preventDefault();await perform(e.submitter,async()=>{await api('connectors/gitlab/token',Object.fromEntries(new FormData(e.target)));e.target.reset();closeModal();await refresh();notice('GitLab 项目已同步，请绑定 Repo 与 Agent。');});});
}
async function configureWebhook(){
 const result=await api('connectors/meeting-webhook/rotate',{});
 showModal('接收其他会议的纪要与待办',`<p>请将以下端点与密钥配置到会议服务或集成工具中。密钥仅显示这一次，轮换后旧密钥立即失效。</p><label>接收端点</label><input readonly value="${esc(result.url)}"><label>Bearer 密钥</label><input readonly type="password" id="webhook-secret" value="${esc(result.token)}"><button class="quiet" id="show-webhook-key">显示密钥</button><p class="modal-note">发送包含 externalId、title、todos、notes 的 JSON。相同会议 ID 自动去重；待办与纪要保留原文依据，需求不足时暂停。无需飞书授权。</p><a target="_blank" rel="noopener noreferrer" href="/assets/meeting-webhook.md">查看接入格式与状态查询</a>`);
 $('#show-webhook-key').addEventListener('click',()=>{$('#webhook-secret').type=$('#webhook-secret').type==='password'?'text':'password';});
 await refresh();
}
function configureAgent(id='bigmodel'){
 const c=state.connectors.find(c=>c.id===id),cli=id!=='bigmodel';
 showModal('连接 '+c.name,`<p class="modal-note">密钥按账号加密保存且不回显。执行器与后端模型分别记录；兼容网关不会被标成官方模型。</p><form id="agent-form"><label for="agent-key">API Key</label><input id="agent-key" type="password" name="apiKey" autocomplete="new-password" required minlength="10" maxlength="4096">${cli?`<label for="agent-base">模型 API 地址</label><input id="agent-base" name="baseUrl" type="url" required value="${esc(c.identity?.baseUrl||(id==='codex'?'https://api.openai.com/v1':'https://api.anthropic.com'))}"><label for="agent-model">后端模型 ID</label><input id="agent-model" name="model" required maxlength="160" value="${esc(c.identity?.model||'')}" placeholder="填写该网关可用的模型 ID"><input type="hidden" name="protocol" value="${id==='codex'?'responses':'anthropic'}"><p class="scope-note">${id==='codex'?'需要 Responses 兼容接口':'需要 Anthropic Messages 兼容接口'}。编码在无外网的云端容器完成，独立测试通过后才创建 PR。</p>`:'<p class="scope-note">需要模型调用与 Managed Agent API 权限。</p>'}<div class="form-footer"><button type="submit" class="button">验证并保存</button></div></form>`);
 $('#agent-form').addEventListener('submit',async e=>{e.preventDefault();await perform(e.submitter,async()=>{const result=await api('agents/'+id+'/settings',Object.fromEntries(new FormData(e.target)));e.target.reset();closeModal();await refresh();notice(result.reinstall?.length?'已保存，部分仓库需更新执行器。':'Agent 已连接。');});});
}

async function bootstrapFeishu(){
 const request=++bootstrapRequest;
 showModal('扫码开通飞书连接','<p>正在准备飞书确认链接…</p>');
 try{const result=await api('connectors/feishu/bootstrap/start',{});if(request!==bootstrapRequest||!$('#modal').open)return;bootstrapId=result.id;await renderBootstrap(result,request);}
 catch(error){if(request===bootstrapRequest&&$('#modal').open)$('#modal-body').innerHTML=`<p class="error-line">${esc(error.message)}</p>`;}
}
async function renderBootstrap(result,request=bootstrapRequest){
 if(request!==bootstrapRequest||bootstrapId!==result.id||!$('#modal').open)return;
 clearTimeout(bootstrapTimer);
 if(result.state==='completed'){
  const current=await api('state');if(request!==bootstrapRequest||bootstrapId!==result.id||!$('#modal').open)return;
  state=current;render();const connected=state.connectors.some(c=>c.id==='feishu'&&c.status==='connected');
  $('#modal-body').innerHTML=`<p>${connected?'飞书已连接，授权已保存，无需再次扫码。':'飞书应用已开通，当前连接需要重新授权。'}</p>${connected?'<p>继续连接自己的 Agent，并为项目绑定 Repo。完成后云端会每五分钟检查授权后生成的新妙记。</p><button class="button" id="bootstrap-done">完成</button>':''}<button class="button secondary" id="bootstrap-authorize">${connected?'重新授权读取妙记':'授权读取妙记'}</button>`;
  $('#bootstrap-done')?.addEventListener('click',closeModal);
  $('#bootstrap-authorize').addEventListener('click',e=>perform(e.target,async()=>{await renderBootstrap(await api('connectors/feishu/bootstrap/'+result.id+'/authorize',{}),request);}));return;
 }
 const ready=['ready','blocked','awaiting_approval'].includes(result.state),waiting=result.state==='awaiting_approval',terminal=['expired','denied'].includes(result.state),connected=state.connectors.some(c=>c.id==='feishu'&&c.status==='connected');
 $('#modal-body').innerHTML=`<p>飞书会在你选择的组织内创建一个专属自建应用，无需填写 App ID 或密钥。应用开通与妙记读取需要分别确认，公司策略可能要求管理员批准。</p><p class="modal-note">当前飞书连接会保留到新授权成功。后续会议由云端每五分钟检查，本机关机后仍可运行。</p>${result.verificationUrl?`<p><a class="button" target="_blank" rel="noopener noreferrer" href="${link(result.verificationUrl)}">${result.state==='user_authorizing'?'在飞书中授权读取妙记':'在飞书中确认开通'} ↗</a></p><p>在飞书页面确认后返回这里，系统会自动继续。</p>`:''}${result.readingMode==='todos'?'<p>待办模式：使用飞书生成的待办及其来源链接；不把逐字稿送入开发流程。仍需飞书批准 AI 产物读取权限。</p>':''}<p id="bootstrap-state">${waiting?'应用已创建；妙记读取权限正在等待公司审批。':result.state==='blocked'?'应用凭据已保存在云端，本次读取授权尚未完成。':ready?'应用已创建，可继续设备授权；无需配置回调地址。':terminal?'本次开通已结束，请重新发起。':result.state==='user_authorizing'?'正在等待本次妙记读取授权确认…':'正在等待确认并配置云端连接…'}</p>${result.error?`<p class="error-line">${esc(messages[result.error]||result.error)}</p>`:''}${connected?'<p>已保存的飞书连接仍处于已连接状态。若无需更换授权，可关闭此流程，继续连接 Agent 与绑定项目。</p><button class="button secondary" id="bootstrap-existing">使用当前连接</button>':''}${ready?`<button class="button" id="bootstrap-authorize">${waiting?'审批通过后重新授权':result.readingMode==='todos'?'授权读取会议纪要待办':'替换当前飞书连接并授权读取妙记'}</button>${result.readingMode!=='todos'?'<button class="button secondary" id="bootstrap-todos">改用会议纪要待办</button>':''}`:terminal?'<button class="button" id="bootstrap-restart">重新发起开通</button>':'<button class="button secondary" id="bootstrap-poll">检查开通状态</button>'}`;
 $('#bootstrap-existing')?.addEventListener('click',()=>{closeModal();refresh();});
 if(ready)$('#bootstrap-authorize').addEventListener('click',e=>perform(e.target,async()=>{const r=await api('connectors/feishu/bootstrap/'+result.id+'/authorize',{});await renderBootstrap(r,request);}));
 if(ready&&$('#bootstrap-todos'))$('#bootstrap-todos').addEventListener('click',e=>perform(e.target,async()=>{await renderBootstrap(await api('connectors/feishu/bootstrap/'+result.id+'/authorize',{mode:'todos'}),request);}));
 if(terminal)$('#bootstrap-restart').addEventListener('click',bootstrapFeishu);
 if(!ready&&!terminal){
  let polling=false;
  const poll=async()=>{if(polling)return;clearTimeout(bootstrapTimer);if(request!==bootstrapRequest||bootstrapId!==result.id||!$('#modal').open)return;polling=true;try{await renderBootstrap(await api('connectors/feishu/bootstrap/'+result.id+'/poll',{}),request);}catch(error){if(request===bootstrapRequest&&bootstrapId===result.id&&$('#modal').open){$('#bootstrap-state').textContent=error.message;bootstrapTimer=setTimeout(poll,10000);}}finally{polling=false;}};
  $('#bootstrap-poll').addEventListener('click',poll);
  if(result.state!=='blocked')bootstrapTimer=setTimeout(poll,Math.max(5000,result.nextPollAt-Date.now()));
 }
}
function renderProjects(){
 const active=state.projects.filter(p=>p.active);const visible=active.filter(p=>(p.name+' '+p.description).toLowerCase().includes(search.toLowerCase()));
 if(!active.length){$('#content').innerHTML='<div class="empty"><div class="connector-icon">▣</div><h2>把已有的项目带进来</h2><p>连接 GitHub Projects 或 Linear 后，项目会自动出现在这里。选择一个项目，绑定 Repo 和 Agent。</p><a class="button" href="#connectors">连接项目平台</a></div>';return;}
 $('#content').innerHTML=`<div class="section-tools"><input id="project-search" type="search" placeholder="搜索项目" aria-label="搜索项目" value="${esc(search)}"><span>${active.length} 个可读项目 · 已同步至云端</span></div><div class="project-list">${visible.map(p=>{const source=state.connectors.find(c=>c.connectionId===p.connection_id),b=p.binding;return `<article class="project-card"><div class="project-heading"><div><p class="project-source">${esc(source?.name)} · ${esc(p.metadata.teams?.map(t=>t.name).join(' / ')||'项目')}</p><h3><a href="${link(p.url)}" target="_blank" rel="noopener noreferrer">${esc(p.name)}</a></h3></div><span class="status ${b?.runnerReady?'good':''}">${b?.runnerReady?'执行器已安装':b?'已绑定 · 待安装':'待绑定 Repo 与 Agent'}</span></div><p class="project-description">${esc(p.description||'来源平台暂无项目说明')}</p>${b?`<div class="project-binding"><span>⑂ ${esc(b.repo)}</span><span>${esc(state.connectors.find(c=>c.id===b.agent)?.name||b.agent)}</span><span>${esc(state.connectors.find(c=>c.id===b.agent)?.identity?.model||'')}</span><span>${b.automatic?'自动执行已开启':'执行前确认'}</span><span>${esc(b.validation.join(' · '))}</span></div>`:''}<div class="project-bottom"><small>同步于 ${new Date(p.synced_at).toLocaleString('zh-CN')}</small><div class="card-actions"><button class="button secondary" data-bind="${p.id}">${b?'编辑绑定':'绑定 Repo 与 Agent'}</button>${b?`<button class="button ${b.runnerReady?'secondary':''}" data-install="${p.id}">${b.runnerReady?'更新云端执行器':'安装云端执行器'}</button><button class="quiet danger" data-unbind="${p.id}">解除绑定</button>`:''}</div></div></article>`;}).join('')||'<div class="empty"><p>没有匹配的项目。</p></div>'}</div>`;
 $('#project-search').addEventListener('input',event=>{const position=event.target.selectionStart;search=event.target.value;renderProjects();$('#project-search').focus();$('#project-search').setSelectionRange(position,position);});
}
function renderTasks(){
 if(!state.tasks.length){$('#content').innerHTML='<div class="empty"><div class="connector-icon">☷</div><h2>下一场会议，就是任务的起点</h2><p>连接会议来源，并完成项目绑定后，明确的开发待办会自动进入这里。需求不完整或项目不明确时，会等待你的确认。</p><a href="#connectors" class="button secondary">查看 Connectors</a></div>';return;}
 $('#content').innerHTML=`<div class="task-list">${state.tasks.map(row=>{const t=row.payload,p=state.projects.find(p=>p.id===row.project_id),runUrl=t.result?.runUrl||t.runUrl||((p?.binding?.repository??'github')==='github'&&p?.binding?.repo&&/^\d+$/.test(t.githubRunId??'')?'https://github.com/'+p.binding.repo+'/actions/runs/'+t.githubRunId:null);return `<article class="task-card"><div class="project-heading"><h3>${esc(t.title)}</h3>${badge(row.status)}</div><div class="task-meta">${esc(p?.name||'项目待确认')} · ${esc(t.meetingTitle)} · ${esc(row.id.slice(0,18))}</div><p>${esc(t.goal)}</p><details><summary>验收条件与会议依据</summary><ul>${t.acceptance.map(a=>`<li>${esc(a)}</li>`).join('')}</ul><blockquote>${esc(t.evidence)}</blockquote>${t.sourceEvidence?.length?`<ul>${t.sourceEvidence.map(c=>`<li><b>${esc(c.title||c.sourceId)}</b>：${esc(c.quote)}</li>`).join('')}</ul>`:''}</details>${t.projectClarificationReason&&!row.project_id?`<p class="error-line">${esc(t.projectClarificationReason)}</p>`:''}${t.requiresClarification?`<p class="error-line">需补充或确认：${esc(t.clarificationReason||'验收依据不完整')}</p>`:''}${t.fidelityReview?`<p class="${t.fidelityReview.approved?'':'error-line'}">需求证据核对：${t.fidelityReview.approved?'通过':esc(t.fidelityReview.violations.join('；'))}</p>`:''}${t.error?`<p class="error-line">${esc(messages[t.error]||t.error)}</p>`:''}<div class="task-links">${t.meetingUrl?`<a target="_blank" rel="noopener noreferrer" href="${link(t.meetingUrl)}">来源会议</a>`:''}${t.original?`<a target="_blank" rel="noopener noreferrer" href="${link(t.original.url)}">原需求</a>`:''}${t.result?`<a target="_blank" rel="noopener noreferrer" href="${link(t.result.pr)}">查看 Pull Request</a><button class="quiet" data-verify="${row.id}">核验交付</button>`:''}${runUrl?`<a target="_blank" rel="noopener noreferrer" href="${link(runUrl)}">云端运行与测试</a>`:''}${['needs_project','needs_info','awaiting_approval','failed'].includes(row.status)?`<button class="quiet" data-approve="${row.id}">${row.status==='failed'?'检查并重试':'确认任务'}</button>`:''}</div></article>`;}).join('')}</div>`;
}
function configure(id){
 const c=state.connectors.find(c=>c.id===id);
 showModal('配置 '+c.name,`<p class="modal-note">先在平台创建 OAuth 应用，将下方地址填写为回调地址。Client Secret 加密保存在云端，保存后不会显示。</p><p><a href="${link(c.setup)}" target="_blank" rel="noopener noreferrer">打开官方应用配置说明</a></p><form id="config-form"><label for="callback">Authorization callback URL</label><input id="callback" readonly value="${esc(c.callback)}"><small>点击地址框可全选复制。</small><label for="client-id">Client ID</label><input id="client-id" name="clientId" required autocomplete="off" value="${esc(c.clientId)}"><label for="client-secret">Client Secret</label><input id="client-secret" name="clientSecret" type="password" autocomplete="new-password" ${c.configured?'':'required'} placeholder="${c.configured?'留空保留已保存的 Secret':'填写 OAuth 应用的 Client Secret'}"><div class="scope-note">${id==='feishu'?'授权用途：读取你自己的身份、可读妙记和文字记录，并通过 offline_access 离线刷新授权。应用管理员须启用 auth:user.id:read / minutes:minutes.search:read / minutes:minutes.transcript:export / offline_access。':id==='github'?'授权用途：读取 Projects 和 Repo、创建 Issue 与 PR、安装选定 Repo 的云端工作流。OAuth App 会请求 repo / project / workflow / read:org / offline_access 权限。':'授权用途：读取项目和需求、创建需求、回填评论。请求 read / issues:create / comments:create 权限。'}</div><div class="form-footer"><button class="button" type="submit">保存应用配置</button></div></form>`);
 $('#callback').addEventListener('click',e=>e.target.select());
 $('#config-form').addEventListener('submit',async e=>{e.preventDefault();await perform(e.submitter,async()=>{await api('connectors/'+id+'/settings',Object.fromEntries(new FormData(e.target)));closeModal();await refresh();notice('应用配置已保存，现在可以点击“授权连接”。');});});
}
async function bind(id){
 const p=state.projects.find(p=>p.id===id),b=p.binding||{};
 const repositories=state.connectors.filter(c=>(c.roles??[c.kind]).includes('repository')&&c.status==='connected');
 const repository=repositories.find(c=>c.connectionId===(b.repositoryConnectionId??b.githubConnectionId))??repositories[0];
 const agents=state.connectors.filter(c=>(c.roles??[c.kind]).includes('agent')&&c.status==='connected'),agent=agents[0];
 if(!repository||!agent){notice('请先在 Connectors 中连接代码仓库和执行 Agent。');return;}
 showModal('绑定 '+p.name,'<p class="modal-note">正在读取你有写入权限的 Repo…</p>');
 try{
 const repos=await api('repositories?connection='+encodeURIComponent(repository.connectionId));if(!repos.length)throw Error('没有可写的 Repo，请检查仓库 Connector 授权范围。');
 const teams=p.metadata.teams||[];
 $('#modal-body').innerHTML=`<p class="modal-note">来源项目提供需求与上下文；这里确定代码要在哪里、由谁开发，以及如何验收。</p><form id="bind-form"><label for="repository-connection">仓库 Connector</label><select id="repository-connection" name="repositoryConnectionId">${repositories.map(c=>`<option value="${esc(c.connectionId)}" ${c.connectionId===repository.connectionId?'selected':''}>${esc(c.name)} · ${esc(c.identity?.name||'')}</option>`).join('')}</select><label for="repo">代码仓库</label><select name="repo" id="repo">${repos.map(r=>`<option value="${esc(r.name)}" ${r.name===b.repo?'selected':''}>${esc(r.name)}</option>`).join('')}</select><label for="agent">执行 Agent</label><select name="agent" id="agent">${agents.map(c=>`<option value="${esc(c.id)}" ${c.id===b.agent?'selected':''}>${esc(c.name)}${c.identity?.model?' · '+esc(c.identity.model):''}</option>`).join('')}</select>${teams.length>1?`<label for="team">需求所属团队</label><select name="teamId" id="team">${teams.map(t=>`<option value="${esc(t.id)}" ${b.teamId===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select>`:''}<label for="validation">验收命令（每行一条）</label><textarea id="validation" name="validation" required placeholder="npm ci&#10;npm test">${esc((b.validation||['npm test']).join('\n'))}</textarea><small>在独立的 GitHub runner 运行。测试通过后才会创建草稿 PR。</small><label for="paths">允许修改的文件或目录（每行一项）</label><textarea id="paths" name="allowedPaths" required placeholder="src/&#10;test/">${esc((b.allowedPaths||['src/','test/','tests/']).join('\n'))}</textarea><small>目录以 / 结尾。工作流和环境配置不允许由编码 Agent 修改。</small><label for="aliases">会议中常用的项目别名（每行一个）</label><textarea name="aliases" id="aliases" placeholder="产品简称或团队常用名">${esc((b.aliases||[]).join('\n'))}</textarea><label class="check-label"><input name="automatic" type="checkbox" ${b.automatic!==false?'checked':''}>符合项目和验收条件的会议待办自动执行</label><div class="form-footer"><button class="button" type="submit">保存并安装执行器</button></div></form>`;
 $('#repository-connection').addEventListener('change',e=>perform(null,async()=>{const list=await api('repositories?connection='+encodeURIComponent(e.target.value));$('#repo').innerHTML=list.map(r=>`<option value="${esc(r.name)}">${esc(r.name)}</option>`).join('');}));
 $('#bind-form').addEventListener('submit',async e=>{e.preventDefault();await perform(e.submitter,async()=>{const data=Object.fromEntries(new FormData(e.target));const lines=v=>v.split('\n').map(s=>s.trim()).filter(Boolean);const selectedRepository=repositories.find(c=>c.connectionId===data.repositoryConnectionId);const binding=await api('projects/'+id+'/bind',{...data,repository:selectedRepository.id,validation:lines(data.validation),allowedPaths:lines(data.allowedPaths),aliases:lines(data.aliases),automatic:data.automatic==='on'});if(!binding.runnerReady)await api('projects/'+id+'/install',{});closeModal();await refresh();notice('项目绑定和云端执行器已准备好，会议检查已排队。');});});
 }catch(error){closeModal();notice(error.message);}
}
function install(id){
 const p=state.projects.find(p=>p.id===id);
 showModal('安装云端执行器',`<p class="modal-note">将在 <strong>${esc(p.binding.repo)}</strong> 的默认分支安装 Progressive Agent 工作流和 runner，并配置加密的执行凭据。之后编码、测试和 PR 创建都在云端完成。</p><p class="info-box">只有项目绑定中允许的文件可由 Agent 修改。测试阶段不持有发布凭据，测试通过后才创建草稿 PR。</p><form id="install-form"><div class="form-footer"><button type="submit" class="button">安装到此 Repo</button></div></form>`);
 $('#install-form').addEventListener('submit',async e=>{e.preventDefault();await perform(e.submitter,async()=>{await api('projects/'+id+'/install',{});closeModal();await refresh();notice('云端执行器已安装。后续符合条件的会议待办会自动进入开发队列。');});});
}
function unbind(id){
 const p=state.projects.find(p=>p.id===id);
 showModal('解除项目绑定',`<p class="modal-note">解除 <strong>${esc(p.name)}</strong> 与 ${esc(p.binding.repo)} 的绑定。后续任务将等待重新选择项目；已有 PR 会保留。正在运行的项目须等待本轮完成。</p><form id="unbind-form"><div class="form-footer"><button class="button" type="submit">解除绑定</button></div></form>`);
 $('#unbind-form').addEventListener('submit',async e=>{e.preventDefault();await perform(e.submitter,async()=>{await api('projects/'+id+'/unbind',{});closeModal();await refresh();notice('绑定已解除，可以将 Repo 绑定至另一个项目。');});});
}
async function verifyDelivery(id){
 showModal('核验云端交付','<p class="modal-note">正在读取仓库中的实际运行和回填记录…</p>');
 try{const result=await api('tasks/'+id+'/verification');$('#modal-body').innerHTML=`<p>云端运行：<strong>${esc(result.run.conclusion||result.run.status)}</strong> · 第 ${esc(result.run.attempt)} 次</p><ul>${result.jobs.map(j=>'<li>'+esc(j.name)+' · '+esc(j.conclusion||j.status)+'</li>').join('')}</ul><p>Pull Request：${result.pull.draft?'草稿 · ':''}${esc(result.pull.state)} · 本任务 ${result.pullCount} 个 PR${result.pullsComplete?'':'（分页未完整）'}</p><p>原需求回填：${result.backfill?result.backfill.comments.length+' 条结果评论'+(result.backfill.complete?'':'（分页未完整）'):'请打开原需求核对'}</p>${result.backfill?.comments.map(c=>'<pre class="modal-note">'+esc(c.body)+'</pre>').join('')||''}`;}catch(error){$('#modal-body').innerHTML='<p class="error-line">'+esc(error.message)+'</p>';}
}
function approve(id){
 const row=state.tasks.find(t=>t.id===id);const projects=state.projects.filter(p=>p.active&&p.binding);
 if(!projects.length){notice('请先完成至少一个项目的 Repo 与 Agent 绑定。');return;}
 showModal('确认开发任务',`<p class="modal-note">${esc(row.payload.title)}</p><form id="approve-form"><label for="task-project">所属项目</label><select name="projectId" id="task-project">${projects.map(p=>`<option value="${p.id}" ${p.id===row.project_id?'selected':''}>${esc(p.name)} · ${esc(p.binding.repo)}</option>`).join('')}</select><label for="acceptance">验收条件（每行一项）</label><textarea name="acceptance" id="acceptance" required>${esc(row.payload.acceptance.join('\n'))}</textarea>${row.status==='failed'&&row.payload.githubRunId&&!row.payload.result?'<label class="check-label"><input type="checkbox" name="restart">绑定或验收命令已修正，重新准备并验证（保留同一任务、需求及 Agent 会话）</label>':''}<div class="form-footer"><button type="submit" class="button">确认并加入队列</button></div></form>`);
 $('#approve-form').addEventListener('submit',async e=>{e.preventDefault();await perform(e.submitter,async()=>{const data=Object.fromEntries(new FormData(e.target));await api('tasks/'+id+'/approve',{projectId:data.projectId,acceptance:data.acceptance.split('\n').map(s=>s.trim()).filter(Boolean),restart:data.restart==='on'});closeModal();await refresh();notice('任务已进入队列，等待下一轮云端调度。');});});
}
function checkFeedback(result){return result.queued?'会议检查已提交至云端。':({agent_not_connected:'请先连接自己的 Agent，再检查会议；已保存的会议来源授权会保留。',meeting_not_connected:'请先连接会议来源，再检查会议。',account_disabled:'当前账号已停用。',already_scheduled:'本轮会议检查已排队或已检查，稍后会自动更新。'}[result.reason]||'会议检查未提交，请刷新后重试。');}
async function perform(button,action){const old=button?.textContent;try{if(button){button.disabled=true;button.textContent='处理中…';}await action();}catch(e){notice(e.message);const existing=$('#modal .form-error');if($('#modal').open){existing?.remove();const p=document.createElement('p');p.className='error-line form-error';p.textContent=e.message;$('#modal-body').append(p);}}finally{if(button?.isConnected){button.disabled=false;button.textContent=old;}}}
$('#content').addEventListener('click',async e=>{
 const b=e.target.closest('button');if(!b||b.closest('form'))return;
 if(b.dataset.revokeInvite)return revokeInvitation(b.dataset.revokeInvite);
 if(b.dataset.bootstrap)return bootstrapFeishu();
 if(b.dataset.config)return configure(b.dataset.config);
 if(b.dataset.agent)return configureAgent(b.dataset.agent);
 if(b.dataset.gitlab)return configureGitlab();
 if(b.dataset.bind)return bind(b.dataset.bind);
 if(b.dataset.install)return install(b.dataset.install);
 if(b.dataset.approve)return approve(b.dataset.approve);
 if(b.dataset.verify)return verifyDelivery(b.dataset.verify);
 if(b.dataset.unbind)return unbind(b.dataset.unbind);
 await perform(b,async()=>{
 if(b.dataset.webhook)await configureWebhook();
 if(b.dataset.sync){const result=await api('connectors/'+b.dataset.sync+'/sync',{});notice(state.connectors.find(c=>c.connectionId===b.dataset.sync)?.kind==='meeting'?checkFeedback(result):'项目同步完成。');}
 if(b.dataset.activate){await api('connectors/'+b.dataset.activate+'/activate',{});notice('Connector 已连接。');}
 if(b.dataset.disconnect){await api('connectors/'+b.dataset.disconnect+'/disconnect',{});notice('连接已断开，后续新任务停止派发。');}
 await refresh();});
});
$('#refresh').addEventListener('click',e=>perform(e.target,refresh));
$('#check-now').addEventListener('click',e=>perform(e.target,async()=>{const r=await api('check',{});notice(checkFeedback(r));}));
$('#logout').addEventListener('click',e=>perform(e.target,async()=>{await api('logout',{});state=null;$('#onboarding').replaceChildren();$('#account-label').textContent='';$('#logout').hidden=true;$('#check-now').hidden=true;location.href='/app';}));
window.addEventListener('hashchange',()=>{if(state)render();});
const params=new URLSearchParams(location.search);if(params.get('connected'))notice('授权成功，连接状态已更新。');if(params.get('error'))notice(messages[params.get('error')]||params.get('error'));
refresh();
// Keep cloud progress current without interrupting a form or background tab.
setInterval(()=>{if(!document.hidden&&!$('#modal').open&&!document.activeElement?.matches('input,textarea,select'))refresh();},15000);
